import { chromium } from 'playwright';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
const root = '/Users/raedmohammed/RaedWorkoutsV2/worktree-v16';
const appUrl = pathToFileURL(path.join(root,'index.html')).href;
const user = 'ar-audit';
const state = {
  schema_version: 2, programme_reference_migration_version: 1,
  current_week: 1, current_block: 1,
  profile: { display_name: 'اختبار', experience: 'returning', created_at: '2026-08-25T00:00:00.000Z' },
  active_session: null, history: [], bodyweight_log: [{date:'2026-09-01', kg:82.5}],
  custom_videos:{}, custom_jn_urls:{}, video_hidden:{}, custom_exercises:[],
  programme_overrides:null, prs:{}, msg_index:0, substitutions:[],
};
const settings = { user_id:user, user_key:'', theme:'light', skin:'hadid', focus_mode:true, show_cues:true,
  rest_seconds:120, vibrate:false, notifications:false, music_platform:'none', block_auto_color:false,
  block_skin_suggestions:{}, block_skin_rejections:{}, lang:'ar', locale_version:1, runner_video_open:true };

const b = await chromium.launch();
const p = await b.newPage({ viewport:{width:390,height:844} });
await p.route('https://**/*', r=>r.abort());
await p.addInitScript(({user,state,settings})=>{
  localStorage.clear();
  localStorage.setItem('raedworkouts.active_user', user);
  localStorage.setItem(`raedworkouts.${encodeURIComponent(user)}.state.v1`, JSON.stringify(state));
  localStorage.setItem(`raedworkouts.${encodeURIComponent(user)}.settings.v1`, JSON.stringify(settings));
},{user,state,settings});
await p.goto(appUrl,{waitUntil:'domcontentloaded'});
await p.waitForTimeout(600);

const dump = async (label, sel) => {
  const txt = await p.evaluate((s)=>{
    const el = document.querySelector(s);
    if(!el) return '(missing)';
    return el.innerText;
  }, sel);
  console.log('=== '+label+' ===');
  console.log(txt);
};

await p.locator('.tab[data-route="history"]').click();
await p.waitForTimeout(300);
await dump('HISTORY PAGE', '#page-history');

// end screen with null session
await p.evaluate(()=>{ window.location.hash='end'; window.dispatchEvent(new HashChangeEvent('hashchange')); });
await p.waitForTimeout(400);
await dump('END PAGE (no session in memory)', '#page-end');

await b.close();
